result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === now` (token expiring at this exact second), the check passes and the token is accepted. It should be `<=`.

There's also a secondary issue: the `catch` block treats all JWT errors identically, hiding useful distinctions between expired tokens and genuinely invalid ones (e.g., bad signature, malformed).

Here's the fixed middleware:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // Fix: use <= so tokens expiring exactly at current time are rejected
    if (decoded.exp <= Math.floor(Date.now() / 1000)) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected errors shouldn't leak internals
    next(err);
  }
}

module.exports = authMiddleware;
```

**Two additional improvements:**

1. `Math.floor(Date.now() / 1000)` instead of `Date.now() / 1000` — JWT `exp` is an integer (Unix seconds), so comparing against a float like `1713484800.123` could produce subtle off-by-one behavior. Flooring ensures the comparison is apples-to-apples.

2. The `catch` now differentiates `TokenExpiredError`, `JsonWebTokenError`, and `NotBeforeError` (the three errors `jsonwebtoken` emits), and falls through to `next(err)` for anything unexpected rather than swallowing it silently.
